; Huffman-compressed text group(s): $4B
; Text $0960: Padequia roots? The drought five years ago destroyed them all.'<4F>That's why I now grow carrots,radishes,and such.
; Text $0961: Looking for someone? Hmm...some time ago,a girl named Alena was here.'<4F>She had three men with her.One was rugged and another snobbish.
; Text $0962: The extinction of Padequia devastated this country's economy.We can't make this country prosper no matter how hard we work.'<4F>Poor King....
; Text $0963: I'm the King of this country.It's been some time since the extinction of Padequia.'<4F>The record states the former King kept a Padequia Seed in the southern cave as a precaution against catastrophe....'<4F>Unfortunately,monsters now lurk in the cave,and we can't get in.'<4F>Sorry,I can't help you.If I had the Padequia Seed,I could....
; Text $0964: Grzz...Grzz...You Monsters of the Southern Cave! Mumble...Mumble...
; Text $0965: Night fishing is the best kind of fishing.'<4F>Some time ago I almost caught a Giant Octopod! I'm not lying!
; Text $0966: You came to see the King? Our King is out working in the fields.'<4F>This country is so poor even the King must work.
; Text $0967: <4E>Alena:'You're looking for Padequia too?'<44>Alena:'Sorry,but we'll get the Padequia Seed first!'
; Text $0968: <4E>Alena:'Hey,it's you,Brey! What are you doing here?'<44>
; Text $0969: <4E>Alena:'What? You're looking for the Padequia Seed with them?'<44>
; Text $096A: <4E>Alena:'You shouldn't have worried.'<44>Alena:'We'll find the Padequia Seed and save Cristo!'
; Text $096B: Huh? <4B>Ohhhhhh! The Padequia Seed.It is indeed! Finally...'<4F>Hurry! Plant the seed in this field! Yes,Padequia grows instantly.'<44><49> plants the Padequia Seed in the field.<44>
; Text $096C: <4E>A Padequia bud shoots out instantly!<4F>Thank you! Our country is saved!'<4F>Take this Padequia Root.'<44><49> obtained the Padequia Root!<43><56><40>
; Text $096D: What? You've found the Padequia Seed? The King will be overjoyed to hear that!'<4F>Please come back again tomorrow morning!
; Text $096E: I'll grow Padequia from now on.Hey! Ho!
; Text $096F: You've found the Padequia Seed? Amazing!
; Text $0970: Thank you for retrieving the Padequia Seed.'<4F>I'm sure this country will thrive again.
; Text $0971: Cheers for Padequia! I'll work even harder in the fields from now on! Cheers!
; Text $0972: Ouch! A Man O'War stung me!
; Text $0973: You saved us! This country will be fine.
; Text $0974: <4E>Brey:'We'll never forget what you've done for us.Thank you!'
; Text $0975: If you sail straight to the west,you'll reach Keeleon Castle.
; Text $0976: Taloon! I went to Endor too,but...'<4F>I lost all my money at the Casino....Sob...
; Text $0977: What do you want? It's so late.
; Text $0978: Hello! Taloon! You look wonderful!
; Text $0979: <4E><44>'The news that you purchased a ship has reached this town.What a feat!'
; Text $097A: Taloon! It's me,Tom's son.'<4F>I decided to work hard and asked the boss to hire me.
; Text $097B: Please save the world.
; Text $097C: <4E><44>'Taloon! Grandpa Tom appreciates what you've done.'<4F>Of course,I appreciate it too....Blush...
; Text $097D: Want to buy something?'<4F>If you want weapons,go to the shop upstairs.
; Text $097E: Taloon! How is your business in Endor?
; Text $097F: Keep it up! You have a cute wife.
