; Huffman-compressed text group(s): $4C
; Text $0980: What? You're traveling in search of a legendary sword? Hmm...
; Text $0981: Oh! Taloon! How can I ever thank you?'<44>Tom:'My son is working hard and is married now.'
; Text $0982: <4E>Tom:'Thanks to one man,my son changed and began working.'
; Text $0983: <4E>Tom:'Hey,Hey! Where do you intend to take me?'
; Text $0984: <4E>Tom:'Doze...Doze...'
; Text $0985: I hear that the people of the Castle in the western country of Santeem are still missing.
; Text $0986: I'm a soldier from Santeem.I was guarding the shrine on the other side.'<4F>Our Princess Alena was saying someone called Necrosaro was suspicious....
; Text $0987: <4E><44>'Oh,my goodness! It's you,Princess! You're alright....Weep...'
; Text $0988: <4E><44>'If you don't want any trouble,leave immediately!'
; Text $0989: I'm a traveler named Healie.'<44>
; Text $098A: Please rescue Ragnar in the Castle!'<4F>You can sneak in if you have a Magic Key.
; Text $098B: <4E><44>'You may find out something in Haville,a northern port town.'
; Text $098C: After the gypsy sisters fled by ship,the King's regulations became even more strict.'<4F>We may never see another ship leave this port.
; Text $098D: <4E><44>'The last ship to leave this port left some time ago.'
; Text $098E: No more ships are in service.
; Text $098F: Magic Keys? Such bizarre things...'<4F>DO EXIST! Unfortunately I don't have one.'<4F>They say alchemists could make one easily.'<4F>I remember alchemists used to live in the southern village,Kievs.
; Text $0990: It seems true that the Ruler of Evil will revive soon.'<4F>I'm afraid we won't be able to take a walk at night anymore.
; Text $0991: Joy is too pretty for my brother.I'll marry her!
; Text $0992: King Balzack of Keeleon appears even less often than before.'<4F>Good for me,I can take it easy.
; Text $0993: I'm here to see Joy,the girl who gave my brother the cold shoulder.'<4F>I'll convince her how good he is!
; Text $0994: Another visitor? Many visitors come to see the prisoners these days....
; Text $0995: King Balzack of Keeleon seems to have a hidden master.'<4F>According to rumor,he's not human.
; Text $0996: <4E><44>'When I told this to a soldier called Ragnar,he left quickly.'
; Text $0997: Is the House of Prophecy still on the shore?
; Text $0998: Ragnar,a soldier from Burland,came searching for the Hero.'<4F>I told him what the Hero looks like.'<4F>The lights are glowing even more radiantly.Your encounter may take place soon.
; Text $0999: The time has come....'<4F>Now that you,the Chosen Ones,have converged,you shall be able to defeat evil.'<4F>Your enemy is the resurrecting Ruler of Evil...whose name is Es....'<4F>Gasp!'<4F>.........
; Text $099A: This is Aktemto,a mining town.'<4F>The man who was at the graveyard passed away too....
; Text $099B: Hack...Hack...will I be alive tomorrow?
; Text $099C: Dig,Dig,Dig...
; Text $099D: I'm a traveling merchant.'<4F>Until recently,I held a desert bazaar in the country of Santeem.'<4F>Now that the bazaar is over,I'm on my way to Monbaraba in the south.'<4F>Well,allow me to do business with you.'<44>
; Text $099E: The Alchemist,Edgar,was assassinated for trying to destroy something called the Secret of Evolution.'<4F>Evolution is how man evolved from apes or something like that,right?'<4F>I wonder what will become of us if we keep evolving!
; Text $099F: I saw a Slime in the village.'<4F>Porta the dog is chasing it barking.
