; Huffman-compressed text group(s): $4D
; Text $09A0: My Mara!'<44>
; Text $09A1: My dear Nara!'<44>
; Text $09A2: You're alright.'<44>
; Text $09A3: What? A Magic Key? Edgar's pupil Orin had one.
; Text $09A4: Oh,my! Porta the dog is very fond of you.'<4F>Or maybe it's just that you smell like a Slime.'<4F>You chatted with a Slime recently?
; Text $09A5: I remembered! Edgar had a secret laboratory somewhere else.'<4F>If I remember correctly,it's in the western cave.I think you'll find a Magic Key there.
; Text $09A6: I came because I heard the secret laboratory of an alchemist was here....
; Text $09A7: Each time a new King is crowned,the terror in this country intensifies.
; Text $09A8: Sometimes I see smoke in the far distance.Am I seeing things?
; Text $09A9: Ha! What are you?
; Text $09AA: I'm Keeleon.I rule this country now,not King Balzack.'<44>
; Text $09AB: Huh? <4B>You! You were chasing Balzack to seek revenge!'<4F>Too bad,Balzack isn't here anymore...Ha,Ha,Ha!'<44>
; Text $09AC: This will be a fun way to pass time.I'll show you how inferior humans are.'<4F>Regret being born with such fragile bodies!
; Text $09AD: Toaaaaaah! <57><4B>Ugahh!
; Text $09AE: You wicked...<57><4B>Ouch!
; Text $09AF: Eeeyaah!<57><4B>
; Text $09B0: Eeee! <57><4B>Hurry! I'll take care of this.You'll go to Keeleon!
; Text $09B1: Ha? What have I been doing all this time?
; Text $09B2: <4E>Ragnar:'Very impressive!'<44>Ragnar:'Hero,let's fight together to save the world!'<44>Ragnar joined the Party!<43><55><44>Ragnar went ahead first and got in the wagon!
; Text $09B3: <4E><44>'That's not true anymore.'
; Text $09B4: Please tell Ragnar that I wish him the best of luck in his journey...'<4F>and I,Healie,thank him greatly....Farewell!
; Text $09B5: Thank you very much.Peace will come to this country too.
; Text $09B6: Forgive me.Bow,Wow!
; Text $09B7: I won't forgive you even if you turn around 100 times!
; Text $09B8: Strange...I don't hear a voice from downstairs anymore.
; Text $09B9: Huh? I was about to become the next subject of an experiment in the Secret of Evolution?'<4F>What's the Secret of Evolution,anyway?
; Text $09BA: Hey! Step aside!
; Text $09BB: I was chased around too much.I won't forget that.
; Text $09BC: He,He,He.I've done something you won't like....'<4F>The Secret of Evolution is already in the hands of Necrosaro.
; Text $09BD: Young girls look healthy...Zzz...Zzz...
; Text $09BE: Kiii! I'm hungry!'<4F>That Balzack drives me hard.'<4F>Blame him,not me! Kiii!
; Text $09BF: Edgar's daughter! You've come! I didn't expect to fight with you again!'<4F>Look at me! I've changed beyond recognition,haven't I? I'm Balzack!'<44>
