; Huffman-compressed text group(s): $4E
; Text $09C0: I've already reached the ultimate form of evolution! My body is like a super-being's.'<44>
; Text $09C1: Even Necrosaro the Master...no that Necrosaro is no match for me.'<4F>Come! You foolish,weak humans!
; Text $09C2: This is Surene.It used to be the Castle Town of Santeem.
; Text $09C3: Monsters started living in Santeem Castle.How terrible....
; Text $09C4: <4E><44>'To find out why the people disappeared,Princess Alena...'<4F>is searching for the man called Necrosaro....La,La,La...
; Text $09C5: I'm Marone the poet.'<4F>I dedicate this requiem to the vanished people of Santeem.<53>'<44>
; Text $09C6: <4E>Nurse:'Stop,Marone! The people of Santeem are still alive!'
; Text $09C7: <4E>Nurse:'I'm worried....Where have the people of Santeem been taken?'
; Text $09C8: I'm a traveling prophetess from Branca.'<4F>In far away Branca,they tell a story of a celestial woman who fell in love with a young woodsman.'<4F>She came down from the sky.'<4F>Do you believe anyone really lives up in the sky?
; Text $09C9: Weep...Weep...neither the kind King nor the people of Santeem live here anymore....
; Text $09CA: I want to comfort this Nurse...'<4F>but I'm not eloquent nor can I sing like Marone.How unbearable....
; Text $09CB: Sss...Sss...
; Text $09CC: Princess Alena! How nice to see you again!'<44>
; Text $09CD: I used to be a soldier of Santeem.'<4F>One day the King tried to tell his people the meaning of his dreams.'<4F>I left the Castle to run an errand that morning....'<4F>The counselor had said that the King would talk about the Ruler of Evil.
; Text $09CE: Uuun...Uuun...
; Text $09CF: I practiced singing so that I could sing as beautifully as Marone.'<4F>Ready? Here it goes....'<44><54><40>
; Text $09D0: Uuun...Uuun...I beg you.Don't let him sing,please....
; Text $09D1: This is the Village of Tempe.
; Text $09D2: <4E><44>'Wow! It's the young woman who defeated the monster some time ago.'
; Text $09D3: Oh,you're...thank you very much for saving the village!
; Text $09D4: Until recently,a monster terrorized this village....'<4F>A pretty woman appeared one day and defeated him.
; Text $09D5: Let's hope for the peace of this world.
; Text $09D6: I'm expecting a child.'<4F>This village will be a lively place.
; Text $09D7: I'll have to work hard for my baby too!
; Text $09D8: My daughter,Nina,will soon have a child.'<4F>I'll do everything to keep peace in this village until the child is grown.
; Text $09D9: They say monsters are now living in Santeem Castle.I'm worried....
; Text $09DA: I can't sleep.'<4F>How true is the rumor that the Ruler of Evil will resurrect?
; Text $09DB: This is the Town of Frenor.
; Text $09DC: There was once a kidnapping in this town.'<4F>The kidnappers took the Golden Bracelet as ransom.
; Text $09DD: The Golden Bracelet was this town's treasure.'<4F>It must have fetched a great price.What a waste!
; Text $09DE: A terribly injured man was brought here recently by a woman.'<4F>He must still be at the inn.
; Text $09DF: The old graveyard keeper knows a lot about the Golden Bracelet.
