; Text $09E0: Do you wish to hear about the Golden Bracelet?
; Text $09E1: Don't be so ignorant.You'd better listen.'<44>
; Text $09E2: The Golden Bracelet is a tool used in magic and alchemy.'<4F>It's said to possess the power to amplify the force of darkness and create the undulation of evil energy.'<4F>Therefore,it could cause a catastrophe if misused.
; Text $09E3: I'm not sure how effective ordinary weapons and armor will be against the evil monster.
; Text $09E4: Have you seen the wedding in Endor? I bet it's gorgeous.
; Text $09E5: In the far eastern country of Branca they tell this story.'<4F>A celestial nymph from the sky fell in love with a young woodsman,and soon they were expecting a child.'<4F>If it's true,what do you think has become of the child?
; Text $09E6: The wedding must be going on in Endor now.
; Text $09E7: The King is at Prince Reed's wedding.
; Text $09E8: I raised Prince Reed.'<4F>I'm sure he'll become a great king....
; Text $09E9: We used to buy armor here,but we won't have to do that anymore.'<4F>From now on we can import as much armor as we want from Endor.
; Text $09EA: This is Jail.You'd better leave or you'll be thrown into it.
; Text $09EB: Darn! It's so boring!
; Text $09EC: I'm working.Come back at night if you want to talk!
; Text $09ED: You've come to accept the King's challenge,haven't you?'<4F>You can only enter the Castle by boat.Good luck!
; Text $09EE: You came because you saw the King's proclamation?
; Text $09EF: Whoever makes the King laugh heartily will receive any reward they desire.
; Text $09F0: I saw a funny jester in a town I once visited.His name was Panon,I think.'<4F>He'll probably be able to make the King laugh....Where could he be now?
; Text $09F1: What should you do when you have a problem? Ignore it because it won't go away!?
; Text $09F2: I couldn't make him laugh a bit.Shoot! I'll try again!
; Text $09F3: Don't talk to me! I'm next.
; Text $09F4: I became nervous in front of the King and forgot my joke!'<4F>I hate myself!
; Text $09F5: <4E>King:'Welcome! Your name is <49>?'<44>King:'Make me laugh.'<44>King:'What's the matter? Hurry!'<44>
; Text $09F6: <4E><49> told many jokes.<44>Alas,the King didn't laugh.<44>King:'You're not funny....Come back with better jokes.'
; Text $09F7: <4E>Panon:'Allow me to speak.I can't make you laugh.'<44>King:'...?'<44>Panon:'However,I believe the people who brought me here surely can!'<44>Panon:'Please give them the Zenithian Helm.'<44>Panon:'They will save the world and bring the days when everyone will be able to laugh without worry.'<44>King:'Hmm...'<44>King:'Panon! You perceived my true intention!'<44>King:'The reason I issued the proclamation was to cheer up this country.'<44>King:'I thought if I brought lots of funny entertainers here,they would make my people happy.'<44>King:'But I've realized you can't cheer up people who have lost hope.'<44>King:'Your request is well taken.I place all my hope in you!'<44>
; Text $09F8: <4E>King:'Take this Zenithian Helm!'<44><49> received the Zenithian Helm!<43><56><40>
; Text $09F9: <4E>King:'...I really meant it,but you can't carry any more things!'<44>King:'Come back to receive it!'
; Text $09FA: <4E>King:'I'll be waiting anxiously for the day to come when all people will be able to laugh wholeheartedly!'<44>King:'Until then,I'll keep issuing the proclamation.'
; Text $09FB: The King must be outraged that I didn't take Lynn to the Castle.'<4F>Tell no one that I'm hiding here,OK?
; Text $09FC: I heard Lynn got safely out of this town with the shaman.'<4F>They must be living happily together somewhere....
; Text $09FD: Ha,Ha,Ha....Panon's show last night was really hilarious.
; Text $09FE: Did you come here across the sea? If so,did you see the rocky,mountainous island where the monsters are said to live?
; Text $09FF: No one who has gone to the island has ever returned.You'd better stay away.
