; Huffman-compressed text group(s): $50
; Text $0A00: I hear there's a big island rimmed by rocky mountains in the far eastern sea.'<4F>They say there's a castle of monsters on the island.
; Text $0A01: Panon,a funny jester,is here now.'<4F>Go to the theater at night if you want to talk to him.
; Text $0A02: Despite many rumors,the Ruler of Evil still hasn't resurrected!'<4F>I dare him to come back to life!
; Text $0A03: I didn't get my turn today either....'<4F>When will I debut?
; Text $0A04: Mumble...Mumble...tonight is the night I'll appear on stage....
; Text $0A05: Mumble...Mumble...I could open many doors with a Magic Key....
; Text $0A06: Lynn,who used to live here,must now be living happily somewhere else.
; Text $0A07: Sorry.I'm seeing this person now.Come back later.
; Text $0A08: I've become pretty popular with girls since I came here.Ha,Ha,Ha!
; Text $0A09: You have companions? You must come alone.
; Text $0A0A: You want to work here? Don't.'<4F>Pufpuf is not easy to master.
; Text $0A0B: This is a Pufpuf room.Would you like to try Pufpuf?
; Text $0A0C: Too bad....Come back again.
; Text $0A0D: I'll start.'<4F>Pufpuf...Pufpuf...'<4F><49>:'..........'<4F>Pufrin...Pufrin...'<4F><49>:'???'<4F>Pufrico...Sooya!'<4F>It's over.'<4F>Now you've been through Pufpuf therapy,you'll be popular with girls.'<4F>Be confident from now on,OK?
; Text $0A0E: It's you,Mara!'<4F>Did you avenge your father? I see....Best of luck to you!
; Text $0A0F: Thanks to Panon,our shows have sold out every night.Heh,Heh...
; Text $0A10: Will I ever have my turn on stage? I'm discouraged.
; Text $0A11: <4E>Panon:'Are you travelers? I'm performing tonight.By all means,please come!'
; Text $0A12: <4E>Panon:'What? Come with you?'
; Text $0A13: <4E>Panon:'Hmm...I must have been hearing things.'
; Text $0A14: <4E>Panon:'I see.The King of Stancia has the Zenithian Helm you'll need for your journey....'<44>Panon:'And to get it,you'll need my talent....'<44>Panon:'By any chance,do you intend to go to Zenithian Castle? No,you don't have to tell me.'<44>Panon:'I understand.I'll accompany you.'<44>Panon joined the Party!<43><55><44>Panon went ahead first and got into the wagon.
; Text $0A15: <4E>Panon:'Hello,you've come at the right moment.'<44>Panon:'I have a tale to tell.'<44>Panon:'Would you hold the edge of my coat? Yes,that's right.Are you ready?'<44>Panon:'Get your hands off my tail!'
; Text $0A16: <4E>Panon:'You want to talk?'<44>Panon:'Not now,please.See me in the dressing room tomorrow around noon.'
; Text $0A17: Wa,Ha,Ha! Panon is sure funny.
; Text $0A18: Gya,Ha,Ha! My belly hurts from laughing!
; Text $0A19: Phuff,Phuff,Phuff! Laughing like this every night is the secret of long life.
; Text $0A1A: I'll use that joke someday!
; Text $0A1B: Yaaeee,Ha,Ha!
; Text $0A1C: It's difficult to replace Panon.'<4F>I've no choice.I must resume the old singing and dancing revue....
; Text $0A1D: I'll try to become as popular as Panon who used to be the star performer here.
; Text $0A1E: This town has the best singing and dancing revue there is!
; Text $0A1F: We can't hear Panon's stories anymore.Too bad....
