; Huffman-compressed text group(s): $51
; Text $0A20: Panon's stories were funny,but I enjoy dance too.
; Text $0A21: That dancer was so cute! I want to see her again!
; Text $0A22: Our guests say they had the same strange dream here.'<4F>The word spread,and no one will stay here.What should I do?
; Text $0A23: When I stay at this inn,I keep having the same dream.'<4F>It's creepy!
; Text $0A24: Welcome to Izmit Village.'<4F>Everyone here is talking about the strange dream.'<4F>You should talk to the people before you stay at the inn.
; Text $0A25: Aren't you Ragnar? Glad to see you looking so great!
; Text $0A26: You're Ragnar's companions?'<4F>You'd better stay at the inn too.
; Text $0A27: Hmm...everyone has the same dream....It's quite strange.
; Text $0A28: This is a school.
; Text $0A29: I came to pick up my child.Shouldn't school be over soon?
; Text $0A2A: Please don't interrupt our studies.
; Text $0A2B: Know what? Pocos,the innkeeper's son,once flew into the sky!
; Text $0A2C: The kid in front of me always turns around.I can't concentrate!
; Text $0A2D: Why do interesting things only happen to Pocos? He's lucky.
; Text $0A2E: First the kidnapping of children,now the strange dream....'<4F>When will we ever be able to live in peace?
; Text $0A2F: Worries never cease,do they?
; Text $0A30: I'm making dessert for my child.'<4F>I love being a mother!
; Text $0A31: Doze...Doze...
; Text $0A32: I forget all my worries when I look at my child's sleeping face.
; Text $0A33: In the south,beyond this cave,stands Burland Castle.'<4F>You knew? You're really somebody,aren't you?
; Text $0A34: Do you know...there's a key which even unlocks jail doors made of iron bars?'<4F>They say the queen of a certain castle has it.'<4F>What? A queen means a woman king!
; Text $0A35: I'm surprised!'<4F>I hear that some people are gathering Zenithian weapons and armor in order to get to Zenithia.
; Text $0A36: Perhaps,the Ruler of Evil has resurrected at last!
; Text $0A37: I'm staying home alone.Aren't I a good child?
; Text $0A38: I owe my present happiness to Ragnar.'<4F>I wonder where he is now.
; Text $0A39: Ragnar! Thanks for what you did.'<4F>I'm now living happily with Alex.
; Text $0A3A: The stars are shining....Look! Our stars!'<4F>Oops,you're not Alex.How embarrassing....
; Text $0A3B: Oh,Soldier! It's me,Alex.'<4F>Thanks for saving me.
; Text $0A3C: I'm Alex.'<4F>I lost my memory once,but now I'm living happily with my wife.
; Text $0A3D: Oh,Ragnar! Welcome back!'<4F>I'm glad you've found the Hero.'<44>
; Text $0A3E: I learned recently that the Zenithian Shield was once in this Castle.'<4F>It seems that in my grandfather's time,the shield was given to the Queen of Gardenbur.'<4F>Gardenbur is the Castle which rises from the heart of the eastern mountains.'<4F>What were my grandfather's intentions? I wonder....
; Text $0A3F: <4E><44>'You already have it? Good!'
