; Huffman-compressed text group(s): $52
; Text $0A40: I hear you can have a strange dream in Izmit Village.
; Text $0A41: Ragnar! Glad to see you're fine.
; Text $0A42: Aren't you Ragnar's companions? Please tell him I wish him the best of luck in his journey.Blush...
; Text $0A43: Hey,Ragnar! You're still here? What a dunce!
; Text $0A44: This is the Castle's treasure chamber.
; Text $0A45: Hmm...I got it!'<4F>The Ruler of Evil must be the monster that completed the ultimate evolutionary step.'<4F>It's written that Master Dragon,fearing the evolved monster's incredible power,imprisoned him underground.'<4F>Now the Ruler of Evil is about to resurrect.'<4F>We must inform Master Dragon immediately!
; Text $0A46: Have you heard the story from the old man in the next room?
; Text $0A47: How can we find Master Dragon?'<4F>Perhaps,we don't need to find him because he should know it by now if he's really a master.
; Text $0A48: Then come back after you hear it.
; Text $0A49: Oh,Ragnar! Glad to see you in good spirits.
; Text $0A4A: The King is upstairs.
; Text $0A4B: Master Dragon lives in Zenithian Castle....'<4F>It's just an old man's silly talk.
; Text $0A4C: I heard the Zenithian Shield was once in this Castle.'<4F>I also heard the King of Stancia had the Zenithian Helm.'<4F>I wonder if he still has it....
; Text $0A4D: I like it outside!'<44>
; Text $0A4E: I'm taking a break!
; Text $0A4F: I'm the only man living in this Castle.'<4F>Phhh,Phhh,Phhh.You envy me,don't you? By the way....'<44>
; Text $0A50: I've been studying the art of prophecy.'<4F>The Queen,recognizing my talent,gave me the Bronze Amulet.'<4F>It's my treasure!
; Text $0A51: What? I didn't hear you.I'm busy now.
; Text $0A52: You must be travelers.'<4F>We've had peace because we've been cut off from the outside world....'<4F>Leave immediately.
; Text $0A53: The Queen is very strict.Watch your manners.
; Text $0A54: Yawn....I'm bored.Where's the excitement?
; Text $0A55: Hello! Why don't you check the drawer? You'll find something.
; Text $0A56: <4E><50>:'I'm counting on you.Catch the thief.'
; Text $0A57: <4E><50>:'I'm counting on you.Get me out of here soon.'
; Text $0A58: Have I seen a suspicious man? Well,I saw a snobbish looking person running south.
; Text $0A59: That Bronze Amulet is my treasure.Return it to me,please.
; Text $0A5A: Where do I think the thief may be?'<4F>If I were the thief,I'd hide in a cave.
; Text $0A5B: Believing in your innocence,I gave you a chance to find the thief.'<4F>Do not betray my faith in you.Go now.
; Text $0A5C: <4E>Seems sound asleep....<44>He's holding the Bronze Amulet against his chest.
; Text $0A5D: Darn!'
; Text $0A5E: Actually,I've believed in your innocence from the beginning.'<4F>I could tell by the look in your eyes.
; Text $0A5F: <49>,you found the thief!'<4F>The soldier who returned first,informed me.'<44>
