; Huffman-compressed text group(s): $53
; Text $0A60: Use this key to get your companion out of jail.'<44>
; Text $0A61: <4E><49> obtained the Final Key!<43><56><4F>Also,take the Zenithian Shield from this Castle's basement.It's yours.'<44>
; Text $0A62: My people told me that you're on journey to defeat the Ruler of Evil.'<4F>I also heard monsters used to live south of here in Rosaville.'<4F>You may find out something there.I suggest you visit Rosaville.
; Text $0A63: I meant it,but you don't seem to be able to carry anymore things.Come back again.
; Text $0A64: Phew...I love breaks!'<44>
; Text $0A65: The Queen returned the Bronze Amulet to me.'<4F>I'm sorry I suspected you even for a moment....'<4F>Forgive me.
; Text $0A66: You caught the real thief?'<4F>I'm glad for you.
; Text $0A67: You're leaving,aren't you? I'll miss you....'<4F>What am I saying?
; Text $0A68: What a bungle I made!'<4F>Those three basements in this Castle I heard about....'<4F>I couldn't find them either....I hate myself....
; Text $0A69: <4E><50>:'You caught the thief? Good! Let me out of here then!'
; Text $0A6A: <4E><50>:'You proved our innocence? Please let me out of here then!'
; Text $0A6B: <4E><50>:'Good to be out! Let's leave!'
; Text $0A6C: <4E><50>:'I'm relieved! Shall we leave now?'
; Text $0A6D: I'm not lying!'<4F>At night,a beautiful girl looks out a window of that tower.
; Text $0A6E: I won't let you pass! You're finished!
; Text $0A6F: I won't let you treat Rosa badly!'<4F>What? You're not here to hurt her? Then I'll tell you something.'<4F>It's said the Staff of Transform is in a royal crypt on the cape southwest of Endor.'<4F>I think if you use it,you'll be able to sneak into the monsters' castle.
; Text $0A70: <4E><44>Alas,it was a skeleton monster.<44>
; Text $0A71: Don't wake me up! I'm sleepy.Mumble...Mumble...
; Text $0A72: Yeek! Let me go!'<4F>What? You used the Staff of Transform to assume the monsters' shapes? I'm relieved....
; Text $0A73: It's surprising you came out of this Castle alive.'<4F>I got it! You used the Staff of Transform to assume the monsters' shapes,right?
; Text $0A74: I knew it!
; Text $0A75: I heard the Staff of Transform is kept in a royal crypt in the Endor area.
; Text $0A76: I have to hurry.Can't be late for the meeting.
; Text $0A77: Phew! I made it.
; Text $0A78: Necrosaro,who has long been absent,has returned....'<4F>Why?
; Text $0A79: As prophesied,Esturk has resurrected!'<4F>Our time has come at last!
; Text $0A7A: What are you doing here? You should be at Aktemto!'<4F>You know Aktemto is on the cape northwest of Keeleon Castle,don't you?
; Text $0A7B: Esturk the Great has emerged from underground!'<4F>If Necrosaro perfects the Secret of Evolution...'<4F>even the celestial master won't meddle with us! Ha,Ha,Ha!
; Text $0A7C: Don't get any closer!'<4F>Esturk the Great is reviving!'<4F>Leave now!
; Text $0A7D: Leave! Now!
; Text $0A7E: You won't? I have no choice then!
; Text $0A7F: The humans who were here took the elfin girl in the tower somewhere.
