; Huffman-compressed text group(s): $54
; Text $0A80: Blub...Blub...Poor Rosa.'<4F>She was hiding from humans but was found again.
; Text $0A81: Rosa was captured!'<4F>They took her towards Izmit.
; Text $0A82: Necrosaro hasn't returned from Aktemto.'<4F>What happened to him?
; Text $0A83: I heard a bad rumor....'<4F>Esturk the Great resurrected but was destroyed by the Hero.I don't believe it!
; Text $0A84: Something is wrong! No one returns from Aktemto.
; Text $0A85: I hear Rosa the Elf,Necrosaro's beloved,was abducted by humans.'<4F>Necrosaro will be furious if he hears this.
; Text $0A86: Hello! How would you like a flying vessel?
; Text $0A87: I wish to say that,but I don't have any yet.'<4F>It's almost complete.All I need is a gas lighter than air.
; Text $0A88: How frustrating! If only we had a gas lighter than air,we could fly!
; Text $0A89: May I take a look at that strange canister you're holding?
; Text $0A8A: Why not?
; Text $0A8B: Wow! There's gas inside!'<4F>This could be....'<4F>Could you possibly give me this canister?
; Text $0A8C: But,please....
; Text $0A8D: I appreciate it! Come back tomorrow,won't you?'<4F>I think I'll be able to give you something wonderful!
; Text $0A8E: Welcome back! I finally completed a flying balloon!'<4F>I'll give you the first one.It's outside!<43><56><40>
; Text $0A8F: The gas from the canister is essential for flying balloons.'<4F>Now I can make many balloons!
; Text $0A90: I can't believe there's a castle up in the sky.
; Text $0A91: Even a balloon won't be able to take you high above the sky to Zenithia.'<4F>But if you use it to survey the world,you may find a way to Zenithia.
; Text $0A92: What happened to <50>? Must see <50> at once!
; Text $0A93: <50>! I've been waiting for you.'<4F>Go see Master Dragon now.'<4F>Or the world will be obliterated!
; Text $0A94: What could that be? I hear voices from the top of the tree.
; Text $0A95: I think I hear someone calling for help.'<4F>They're saying to come up in groups of three....
; Text $0A96: I don't hear any more voices....
; Text $0A97: Oh,you completed the rescue? I'm glad.
; Text $0A98: Please help me.'<4F>I'm Lucia.I came here to collect the leaves of world trees...'<4F>but was attacked by monsters.They broke my wings.'<4F>Would you take me back to Zenithian Castle?
; Text $0A99: You must think it's dangerous to go to Zenithian Castle.
; Text $0A9A: Oh,you will!'<44>
; Text $0A9B: Your group is full now.'<4F>I'll wait until you come back with fewer companions.
; Text $0A9C: To enter Zenithian Tower,you must be equipped with all of the Zenithian weapons and armor.'<44>
; Text $0A9D: I feel it.The Zenithian Sword is hidden somewhere in this tree.'<44>
; Text $0A9E: Shall we leave?'<44>Lucia joined the Party!<43><55><4B>
; Text $0A9F: This is Zenithian Castle.
