; Huffman-compressed text group(s): $55
; Text $0AA0: This is Master Dragon's castle.
; Text $0AA1: I hear something horribly evil is coming to life on earth.
; Text $0AA2: I wonder how many hundreds of years it's been since wingless people came here.
; Text $0AA3: It was terrifying!'<4F>The evil undulation rose from the earth beneath us and then penetrated the clouds.
; Text $0AA4: Twirl...Twirl...
; Text $0AA5: <4E>Lita:'Huh!'
; Text $0AA6: Humans! Lita,don't talk to them!'<44>Lita:'I won't,sister.Huh!'
; Text $0AA7: I'm Master Dragon.I rule this Castle.'<4F>I oversee the world from this place.'<4F>I already know what brought you here.'<4F>Unfortunately even I cannot stop Necrosaro's ultimate evolution....'<4F>I'm not as omnipotent as you might expect.'<4F>By the way,humans are curious creatures.'<4F>Inherently weak humans can do miraculous things at times.'<4F>I'll place my hope in you!'<44>
; Text $0AA8: <49> comes back to life!<44>
; Text $0AA9: <49>,the Hero,a Zenithian and human descendant!'<4F>You might be able to defeat the ultimate evil form.'<4F>I bestow upon you the power of my hope!'<44>
; Text $0AAA: <4E>The Zenithian Sword starts to glow fiercely!
; Text $0AAB: <49>,go now!'<4F>Beneath this Castle is the entrance to the world of darkness.'<4F>That Zenithian Sword will be a tremendous help to you.
; Text $0AAC: You can't read any of those books,can you?'<4F>Ask those two to read for you.
; Text $0AAD: Do you wish to read this book?
; Text $0AAE: About the Secret of Evolution.Ehem...'<4F>The Secret of Evolution is a method to distort the natural evolutionary processes.'<4F>Through the use of this method,unnatural beings may be created.'<4F>The Secret of Evolution is the source of all evil things.'<4F>It must not be handed down to future generations.Bury it deep underground....'<4F>...says the book.'<4F>But ages later,it was rediscovered.'<4F>The rancor of those affected by it may have led to the rediscovery.
; Text $0AAF: Very well....Perhaps later....
; Text $0AB0: The History of a Battle.Ehem...'<4F>Long ago,Esturk,the Ruler of Evil,created a terrible thing,the Secret of Evolution.'<4F>Esturk used it to evolve into a super being.'<4F>Upon discovering this,the Zenithians,joined by Master Dragon,fought against Esturk.'<4F>After a long battle,Esturk was imprisoned deep underground.'<4F>DoeseeielehaeeeufdE
